--
-- Name: activate_attachment(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_attachment(p_id uuid, p_drive_file_id text, p_drive_folder_id text, p_max_active integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_att attachments%rowtype;
  v_open boolean;
  v_active integer;
  v_published boolean := false;
begin
  select * into v_att from attachments where id = p_id for update;
  if not found then
    raise exception 'attachment_not_found';
  end if;
  if v_att.status <> 'pending' then
    raise exception 'attachment_not_pending';
  end if;

  if v_att.resource_id is not null then
    perform 1 from resources where id = v_att.resource_id for update;
    -- Retire first: the one-active-file index would refuse the activation otherwise.
    update attachments set status = 'deleted', deleted_at = now()
     where resource_id = v_att.resource_id and status = 'active' and id <> p_id;
    update resources set status = 'active' where id = v_att.resource_id and status = 'pending';
    v_published := found;
  else
    if v_att.submission_id is not null then
      select s.is_active and s.score is null and s.graded_at is null and a.status = 'active'
             and not (a.enforce_deadline and now() > a.due_date)
        into v_open
        from submissions s
        join assignments a on a.id = s.assignment_id
       where s.id = v_att.submission_id
         for update of s;
      if not coalesce(v_open, false) then
        raise exception 'submission_closed';
      end if;
      select count(*) into v_active from attachments where submission_id = v_att.submission_id and status = 'active';
    elsif v_att.announcement_id is not null then
      perform 1 from announcements where id = v_att.announcement_id for update;
      select count(*) into v_active from attachments where announcement_id = v_att.announcement_id and status = 'active';
    else
      perform 1 from assignments where id = v_att.assignment_id for update;
      select count(*) into v_active from attachments where assignment_id = v_att.assignment_id and status = 'active';
    end if;
    if v_active >= p_max_active then
      raise exception 'attachment_cap_reached';
    end if;
  end if;

  update attachments
     set status = 'active', drive_file_id = p_drive_file_id, drive_folder_id = p_drive_folder_id
   where id = p_id;

  return v_published;
end;
$$;


--
-- Name: activate_global_persona(uuid, public.persona_name); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_global_persona(p_profile_id uuid, p_persona public.persona_name) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  update persona_assignments set status = 'active'
   where profile_id = p_profile_id and persona_name = p_persona and scope_type = 'global';
  if not found then
    insert into persona_assignments (profile_id, persona_name, scope_type, scope_id, status)
    values (p_profile_id, p_persona, 'global', null, 'active');
  end if;
end;
$$;


--
-- Name: add_guardian(uuid, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_guardian(p_student_id uuid, p_name text, p_phone text, p_email text, p_relationship text, p_is_primary boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('guardians:' || p_student_id::text, 0));
  if p_is_primary then
    update guardians set is_primary = false where student_id = p_student_id and is_primary;
  end if;
  insert into guardians (student_id, name, phone, email, relationship, is_primary)
  values (p_student_id, p_name, p_phone, p_email, p_relationship, p_is_primary)
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: apply_fx_conversions(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_fx_conversions(p_version text, p_rows jsonb) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_receipts integer;
  v_payslips integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('fx:conversions', 0));
  if fx_source_version() <> p_version then
    raise exception 'fx_source_changed';
  end if;

  update receipts d
     set base_currency = x.base_currency, base_total = x.base_total, fx_rate = x.fx_rate, fx_rate_id = x.fx_rate_id
    from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb))
         as x(kind text, id uuid, base_currency text, base_total numeric, fx_rate numeric, fx_rate_id uuid)
   where x.kind = 'receipt' and d.id = x.id;
  get diagnostics v_receipts = row_count;

  update payslips d
     set base_currency = x.base_currency, base_total = x.base_total, fx_rate = x.fx_rate, fx_rate_id = x.fx_rate_id
    from jsonb_to_recordset(coalesce(p_rows, '[]'::jsonb))
         as x(kind text, id uuid, base_currency text, base_total numeric, fx_rate numeric, fx_rate_id uuid)
   where x.kind = 'payslip' and d.id = x.id;
  get diagnostics v_payslips = row_count;

  return v_receipts + v_payslips;
end;
$$;


--
-- Name: assert_issue_allowed(text, uuid, text, numeric, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_issue_allowed(p_kind text, p_party_id uuid, p_currency text, p_total numeric, p_billing_period text, p_source_fingerprint text, p_source_from timestamp with time zone, p_source_to timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_number text;
begin
  perform pg_advisory_xact_lock(hashtextextended('finance-issue:' || p_kind || ':' || p_party_id::text, 0));

  if p_billing_period is not null then
    if p_source_fingerprint is null or p_source_from is null or p_source_to is null then
      raise exception 'billing_source_required';
    end if;
    if billing_source_fingerprint(p_kind, p_party_id, p_source_from, p_source_to) <> p_source_fingerprint then
      raise exception 'billing_source_changed';
    end if;
    return;
  end if;

  -- A document that bills no particular month: refuse its identical twin issued moments ago.
  -- A double-submit guard, not a uniqueness rule - two genuinely separate documents for one
  -- party are legitimate, so the window is short.
  if p_kind = 'receipt' then
    select number into v_number from receipts
     where student_id = p_party_id and not voided and billing_period is null
       and currency = p_currency and total = p_total and created_at > now() - interval '2 minutes'
     order by created_at desc limit 1;
  else
    select number into v_number from payslips
     where tutor_id = p_party_id and not voided and billing_period is null
       and currency = p_currency and total = p_total and created_at > now() - interval '2 minutes'
     order by created_at desc limit 1;
  end if;
  if v_number is not null then
    raise exception 'duplicate_recent:%', v_number;
  end if;
end;
$$;


--
-- Name: assert_session_hours_unbilled(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_session_hours_unbilled(p_tutor_id uuid, p_month text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_number text;
begin
  if p_tutor_id is null or p_month is null then
    return;
  end if;
  -- The key issue_payslip_doc takes for this payee.
  perform pg_advisory_xact_lock(hashtextextended('finance-issue:payslip:' || p_tutor_id::text, 0));
  select number into v_number
    from payslips
   where voided = false and billing_period = p_month and tutor_id = p_tutor_id
   limit 1;
  if v_number is not null then
    raise exception
      'Session hours are locked: pay slip % already billed % for this payee. Void it first, then correct and reissue.',
      v_number, p_month
      using errcode = 'check_violation';
  end if;
end;
$$;


--
-- Name: assert_student_hours_unbilled(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_student_hours_unbilled(p_student_id uuid, p_month text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_number text;
begin
  if p_student_id is null or p_month is null then
    return;
  end if;
  -- The key issue_receipt_doc takes for this student.
  perform pg_advisory_xact_lock(hashtextextended('finance-issue:receipt:' || p_student_id::text, 0));
  select number into v_number
    from receipts
   where voided = false and billing_period = p_month and student_id = p_student_id
   limit 1;
  if v_number is not null then
    raise exception
      'Session hours are locked: receipt % already billed % for this student. Void it first, then correct and reissue.',
      v_number, p_month
      using errcode = 'check_violation';
  end if;
end;
$$;


--
-- Name: assign_class_tutor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_class_tutor(p_class_id uuid, p_tutor_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role user_role;
begin
  perform lock_tutor_persona(p_tutor_id);

  select role into v_role from profiles
   where id = p_tutor_id and role in ('tutor', 'mentor') and status = 'active'
     for share;
  if not found then
    raise exception 'tutor_not_assignable';
  end if;
  perform 1 from classes where id = p_class_id and status = 'active' for share;
  if not found then
    raise exception 'class_not_active';
  end if;

  insert into class_tutors (tutor_id, class_id, active)
  values (p_tutor_id, p_class_id, true)
  on conflict (tutor_id, class_id) do update set active = true;

  -- A dedicated mentor who teaches needs the tutor persona for the teaching workflows.
  if v_role = 'mentor' then
    perform activate_global_persona(p_tutor_id, 'tutor');
  end if;
end;
$$;


--
-- Name: assign_mentorship(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_mentorship(p_mentor_id uuid, p_student_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  -- Same key as remove_mentorship, so an assign and a remove of one pair take turns.
  perform pg_advisory_xact_lock(hashtextextended('mentorship:' || p_mentor_id::text || ':' || p_student_id::text, 0));

  perform 1 from profiles where id = p_mentor_id and role in ('mentor', 'tutor') and status = 'active' for share;
  if not found then
    raise exception 'mentor_not_assignable';
  end if;
  perform 1 from profiles where id = p_student_id and role = 'student' and status = 'active' for share;
  if not found then
    raise exception 'student_not_active';
  end if;

  insert into mentorships (mentor_id, student_id, active)
  values (p_mentor_id, p_student_id, true)
  on conflict (mentor_id, student_id) do update set active = true
  returning id into v_id;

  -- The persona is what grants access; the link alone grants nothing.
  insert into persona_assignments (profile_id, persona_name, scope_type, scope_id, status)
  values (p_mentor_id, 'mentor', 'student', p_student_id, 'active')
  on conflict (profile_id, persona_name, scope_id) do update set status = 'active', scope_type = 'student';

  return v_id;
end;
$$;


--
-- Name: billing_source_fingerprint(text, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.billing_source_fingerprint(p_kind text, p_party_id uuid, p_from timestamp with time zone, p_to timestamp with time zone) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_source text;
begin
  if p_kind = 'payslip' then
    select count(*)::text || '|' ||
           coalesce(sum(extract(epoch from (s.actual_end - s.actual_start))), 0)::text || '|' ||
           coalesce(string_agg(s.id::text || ':' || s.class_id::text || ':' || coalesce(s.subject_id::text, '')
                               || ':' || coalesce(s.actual_end::text, ''), ',' order by s.id), '')
      into v_source
      from class_sessions s
      join classes c on c.id = s.class_id
     where s.tutor_id = p_party_id
       and s.actual_start >= p_from and s.actual_start < p_to
       and c.status <> 'archived';
  elsif p_kind = 'receipt' then
    select count(*)::text || '|' ||
           coalesce(sum(extract(epoch from (s.actual_end - s.actual_start))), 0)::text || '|' ||
           coalesce(string_agg(s.id::text || ':' || s.class_id::text || ':' || coalesce(s.subject_id::text, '')
                               || ':' || coalesce(s.actual_end::text, ''), ',' order by s.id), '')
      into v_source
      from attendance a
      join class_sessions s on s.id = a.session_id
      join classes c on c.id = s.class_id
     where a.student_id = p_party_id
       and a.status in ('present', 'late')
       and s.actual_start >= p_from and s.actual_start < p_to
       and c.status <> 'archived';
  else
    raise exception 'invalid_kind';
  end if;
  return md5(v_source);
end;
$$;


