--
-- Name: claim_pending_emails(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_pending_emails(p_limit integer) RETURNS SETOF public.pending_emails
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update pending_emails
     set status = 'sending', claimed_at = now()
   where id in (
     select id from pending_emails
      where status = 'pending'
      order by created_at
      limit p_limit
      for update skip locked
   )
  returning *;
$$;


--
-- Name: count_active_enrollments_per_class(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.count_active_enrollments_per_class() RETURNS TABLE(class_id uuid, student_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select e.class_id, count(*)::bigint
  from enrollments e
  where e.active = true
  group by e.class_id
$$;


--
-- Name: create_conversation(public.conversation_kind, text, uuid, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_conversation(p_kind public.conversation_kind, p_title text, p_created_by uuid, p_direct_key text, p_participant_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
  v_created boolean := false;
begin
  if coalesce(array_length(p_participant_ids, 1), 0) < 2 then
    raise exception 'too_few_participants';
  end if;

  if p_kind = 'direct' then
    if p_direct_key is null then
      raise exception 'direct_key_required';
    end if;
    perform pg_advisory_xact_lock(hashtextextended('direct-conversation:' || p_direct_key, 0));
    select id into v_id from conversations where kind = 'direct' and direct_key = p_direct_key;
  end if;

  if v_id is null then
    insert into conversations (kind, title, created_by, last_message_at, direct_key)
    values (p_kind, p_title, p_created_by, now(), case when p_kind = 'direct' then p_direct_key end)
    returning id into v_id;
    v_created := true;
  end if;

  insert into conversation_participants (conversation_id, profile_id)
  select v_id, pid from unnest(p_participant_ids) as pid
  on conflict (conversation_id, profile_id) do nothing;

  return jsonb_build_object('id', v_id, 'created', v_created);
end;
$$;


