--
-- Name: default_reminder_creator(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.default_reminder_creator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  if new.created_by is null then
    new.created_by := new.user_id;
  end if;
  return new;
end;
$$;


--
-- Name: edit_assignment_and_reclassify(uuid, text, text, timestamp with time zone, text, text, numeric, boolean, text, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_assignment_and_reclassify(p_id uuid, p_title text, p_description text, p_due_date timestamp with time zone, p_attachment_drive_link text, p_topic text, p_max_marks numeric, p_enforce_deadline boolean, p_type text, p_expects_submission boolean, p_ends_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update assignments set
    title = p_title,
    description = p_description,
    due_date = p_due_date,
    attachment_drive_link = p_attachment_drive_link,
    topic = p_topic,
    max_marks = p_max_marks,
    enforce_deadline = p_enforce_deadline,
    type = p_type,
    expects_submission = p_expects_submission,
    ends_at = p_ends_at
  where id = p_id;

  if not found then
    raise exception 'assignment % not found', p_id;
  end if;

  -- Re-derive lateness against the new deadline, matching set_submission_status() (0009) and
  -- the app's computeStatus: submitted AFTER the due instant is 'late', at-or-before is
  -- 'submitted'. Only rows whose verdict actually changes are written.
  update submissions set
    status = case when submitted_at > p_due_date then 'late' else 'submitted' end
  where assignment_id = p_id
    and status <> (case when submitted_at > p_due_date then 'late' else 'submitted' end);
end;
$$;


--
-- Name: enforce_student_subject_once_on_class(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_student_subject_once_on_class() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_student uuid;
begin
  if new.subject_id is null or new.status = 'archived' then
    return new;
  end if;
  -- Only a new subject or a return from the archive creates a pair.
  if old.subject_id is not distinct from new.subject_id and old.status <> 'archived' then
    return new;
  end if;

  for v_student in
    select student_id from enrollments where class_id = new.id and active order by student_id
  loop
    perform lock_student_subjects(v_student);
    if student_takes_subject_elsewhere(v_student, new.subject_id, new.id) then
      raise exception 'subject_already_taken';
    end if;
  end loop;
  return new;
end;
$$;


--
-- Name: enforce_student_subject_once_on_enrollment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_student_subject_once_on_enrollment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_subject uuid;
begin
  if not new.active then
    return new;
  end if;
  -- An update that neither activates the row nor moves it changes no pair.
  if tg_op = 'UPDATE' and old.active and old.class_id = new.class_id and old.student_id = new.student_id then
    return new;
  end if;

  select subject_id into v_subject
    from classes
   where id = new.class_id and status <> 'archived';
  if v_subject is null then
    return new;
  end if;

  perform lock_student_subjects(new.student_id);
  if student_takes_subject_elsewhere(new.student_id, v_subject, new.class_id) then
    raise exception 'subject_already_taken';
  end if;
  return new;
end;
$$;


--
-- Name: ensure_day_session(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_day_session(p_class_id uuid, p_session_date date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended('day-session:' || p_class_id::text || ':' || p_session_date::text, 0));

  select id into v_id
    from class_sessions
   where class_id = p_class_id and session_date = p_session_date
   order by actual_start asc nulls first, created_at asc
   limit 1;
  if v_id is not null then
    return v_id;
  end if;

  insert into class_sessions (class_id, session_date)
  values (p_class_id, p_session_date)
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: ensure_submission_for_student(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_submission_for_student(p_assignment_id uuid, p_student_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_assignment assignments%rowtype;
  v_id uuid;
begin
  select * into v_assignment from assignments where id = p_assignment_id and status = 'active';
  if not found then
    raise exception 'assignment_not_found';
  end if;
  if v_assignment.enforce_deadline and now() > v_assignment.due_date then
    raise exception 'deadline_passed';
  end if;
  perform 1 from profiles where id = p_student_id and status = 'active' for share;
  if not found then
    raise exception 'actor_not_active';
  end if;
  perform 1 from enrollments
   where student_id = p_student_id and class_id = v_assignment.class_id and active;
  if not found then
    raise exception 'not_enrolled';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_assignment_id::text || ':' || p_student_id::text, 0));

  select id into v_id from submissions
   where assignment_id = p_assignment_id and student_id = p_student_id and is_active;
  if found then
    return jsonb_build_object('id', v_id, 'created', false);
  end if;

  insert into submissions (assignment_id, student_id, drive_link, file_name, is_active)
  values (p_assignment_id, p_student_id, null, null, true)
  returning id into v_id;
  return jsonb_build_object('id', v_id, 'created', true);
end;
$$;


--
-- Name: erase_profile_guarded(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.erase_profile_guarded(p_target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_status user_status;
  v_erased timestamptz;
  v_auth uuid;
begin
  select status, erased_at, auth_user_id into v_status, v_erased, v_auth
    from profiles where id = p_target for update;
  if not found then
    return jsonb_build_object('outcome', 'not_found', 'auth_user_id', null);
  end if;
  if v_erased is not null then
    return jsonb_build_object('outcome', 'already_erased', 'auth_user_id', v_auth);
  end if;
  if v_status <> 'disabled' then
    return jsonb_build_object('outcome', 'not_disabled', 'auth_user_id', null);
  end if;

  -- Pastoral notes ABOUT the person, and guardians' contact details (third-party PII). The
  -- profile row is kept for audit and finance references, so its FK cascades never fire.
  delete from mentee_notes where student_id = p_target;
  delete from guardians where student_id = p_target;

  update profiles
     set full_name = 'Erased user',
         email = 'erased+' || p_target::text || '@erased.invalid',
         phone = null,
         guardian_name = null,
         guardian_phone = null,
         date_of_birth = null,
         country = null,
         class_level = null,
         qualifications = null,
         bio = null,
         setup_code_hash = null,
         setup_code_expires_at = null,
         status = 'disabled',
         erased_at = now()
   where id = p_target;

  return jsonb_build_object('outcome', 'erased', 'auth_user_id', v_auth);
end;
$$;


--
-- Name: finance_totals_base(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_totals_base(p_kind text) RETURNS TABLE(base_currency text, base_total numeric, converted_count bigint, unconverted_count bigint)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select
    (select base_currency from org_settings limit 1),
    coalesce(
      sum(r.base_total) filter (
        where r.base_total is not null
          and r.base_currency = (select base_currency from org_settings limit 1)
      ),
      0
    )::numeric,
    count(*) filter (
      where r.base_total is not null
        and r.base_currency = (select base_currency from org_settings limit 1)
    )::bigint,
    count(*) filter (
      where r.base_total is null
        or r.base_currency is distinct from (select base_currency from org_settings limit 1)
    )::bigint
  from receipts r
  where r.voided = false
  having p_kind = 'receipt'
  union all
  select
    (select base_currency from org_settings limit 1),
    coalesce(
      sum(p.base_total) filter (
        where p.base_total is not null
          and p.base_currency = (select base_currency from org_settings limit 1)
      ),
      0
    )::numeric,
    count(*) filter (
      where p.base_total is not null
        and p.base_currency = (select base_currency from org_settings limit 1)
    )::bigint,
    count(*) filter (
      where p.base_total is null
        or p.base_currency is distinct from (select base_currency from org_settings limit 1)
    )::bigint
  from payslips p
  where p.voided = false
  having p_kind = 'payslip';
$$;


--
-- Name: fx_source_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fx_source_version() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select md5(
    coalesce((select base_currency from org_settings limit 1), '') || '|' ||
    coalesce((select string_agg(id::text || ':' || currency || ':' || base_currency || ':' || rate::text || ':' || effective_from::text,
                                ',' order by id)
                from exchange_rates), '')
  );
$$;


--
-- Name: guard_assigned_reminder_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_assigned_reminder_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or public.is_active_admin() then
    return new;
  end if;
  -- Identity columns are immutable on ANY non-admin update - checked FIRST so an assignee
  -- can't set new.created_by = new.user_id to slip past the personal-reminder shortcut.
  if new.created_by is distinct from old.created_by
     or new.user_id is distinct from old.user_id
     or new.class_id is distinct from old.class_id then
    raise exception 'reminder ownership is immutable';
  end if;
  -- Personal reminder (by the ORIGINAL row): owner has full control.
  if old.created_by = old.user_id then
    return new;
  end if;
  -- The creator of an assigned reminder may edit it freely.
  if public.current_profile_id() = old.created_by then
    return new;
  end if;
  -- Otherwise the actor is the assignee: only a mark-done (is_sent false->true) is allowed.
  if new.title is distinct from old.title
     or new.description is distinct from old.description
     or new.remind_at is distinct from old.remind_at then
    raise exception 'assignee may only mark an assigned reminder done';
  end if;
  if old.is_sent and not new.is_sent then
    raise exception 'assignee may not reopen a completed reminder';
  end if;
  return new;
end;
$$;


--
-- Name: guard_billed_attendance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_billed_attendance() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old_student uuid;
  v_old_month text;
  v_new_student uuid;
  v_new_month text;
begin
  if tg_op = 'UPDATE'
     and new.student_id is not distinct from old.student_id
     and new.session_id is not distinct from old.session_id
     and (new.status in ('present', 'late')) = (old.status in ('present', 'late')) then
    return null;
  end if;

  -- A mark bills toward the month its session's recorded start falls in. A session deleted in
  -- this statement is already gone here (its marks go by cascade); its own guard checked them.
  if tg_op <> 'INSERT' and old.status in ('present', 'late') then
    v_old_student := old.student_id;
    select institute_month(s.actual_start) into v_old_month
      from class_sessions s where s.id = old.session_id for share;
  end if;
  if tg_op <> 'DELETE' and new.status in ('present', 'late') then
    v_new_student := new.student_id;
    select institute_month(s.actual_start) into v_new_month
      from class_sessions s where s.id = new.session_id for share;
  end if;

  -- Locked in a fixed order, as the session guard does for payees.
  if v_new_student is not null and (v_old_student is null or v_new_student::text < v_old_student::text) then
    perform assert_student_hours_unbilled(v_new_student, v_new_month);
    perform assert_student_hours_unbilled(v_old_student, v_old_month);
  else
    perform assert_student_hours_unbilled(v_old_student, v_old_month);
    perform assert_student_hours_unbilled(v_new_student, v_new_month);
  end if;
  return null;
end;
$$;


--
-- Name: guard_billed_session_hours(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_billed_session_hours() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_old_tutor uuid;
  v_old_month text;
  v_new_tutor uuid;
  v_new_month text;
  v_student uuid;
begin
  if tg_op = 'UPDATE'
     and new.actual_start is not distinct from old.actual_start
     and new.actual_end is not distinct from old.actual_end
     and new.tutor_id is not distinct from old.tutor_id then
    -- Only the fields that determine pay. Summary, feedback and staff notes stay editable
    -- after issuance: they are the pastoral record, often written up later.
    return new;
  end if;

  -- A session counts toward the month its recorded start falls in; one with no start
  -- counts toward none.
  if tg_op <> 'INSERT' and old.actual_start is not null then
    v_old_tutor := old.tutor_id;
    v_old_month := institute_month(old.actual_start);
  end if;
  if tg_op <> 'DELETE' and new.actual_start is not null then
    v_new_tutor := new.tutor_id;
    v_new_month := institute_month(new.actual_start);
  end if;

  -- Both sides, locked in a fixed order so two sessions moved in opposite directions
  -- between two payees cannot deadlock.
  if v_new_tutor is not null and (v_old_tutor is null or v_new_tutor::text < v_old_tutor::text) then
    perform assert_session_hours_unbilled(v_new_tutor, v_new_month);
    perform assert_session_hours_unbilled(v_old_tutor, v_old_month);
  else
    perform assert_session_hours_unbilled(v_old_tutor, v_old_month);
    perform assert_session_hours_unbilled(v_new_tutor, v_new_month);
  end if;

  -- The students a receipt bills this session to: everyone with a counting mark on it. A new
  -- session has no marks, and a change of tutor alone does not change what a student is billed.
  if tg_op = 'DELETE'
     or (tg_op = 'UPDATE' and (new.actual_start is distinct from old.actual_start
                               or new.actual_end is distinct from old.actual_end)) then
    for v_student in
      select a.student_id
        from attendance a
       where a.session_id = old.id and a.status in ('present', 'late')
       group by a.student_id
       order by a.student_id::text
    loop
      perform assert_student_hours_unbilled(v_student, institute_month(old.actual_start));
      if tg_op = 'UPDATE' then
        perform assert_student_hours_unbilled(v_student, institute_month(new.actual_start));
      end if;
    end loop;
  end if;

  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: guard_class_accepts_content(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_class_accepts_content() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_new jsonb := to_jsonb(new);
  v_old jsonb;
  v_class uuid := (v_new ->> 'class_id')::uuid;
begin
  -- Academy-wide rows (announcements, meet links, events with no class) are not class content.
  if v_class is null then
    return new;
  end if;

  if tg_op = 'UPDATE' then
    v_old := to_jsonb(old);
    if not (
      (v_old ->> 'class_id') is distinct from (v_new ->> 'class_id')
      or (v_new ? 'status' and v_new ->> 'status' in ('active', 'pending')
          and (v_old ->> 'status') not in ('active', 'pending'))
      or (v_new ? 'active' and (v_new ->> 'active')::boolean
          and not coalesce((v_old ->> 'active')::boolean, false))
    ) then
      return new;
    end if;
  else
    -- A row inserted already archived or inactive adds nothing live.
    if (v_new ? 'active' and not (v_new ->> 'active')::boolean)
       or (v_new ? 'status' and v_new ->> 'status' not in ('active', 'pending')) then
      return new;
    end if;
  end if;

  -- FOR SHARE needs more than SELECT on classes, which is why this runs as the function owner.
  perform 1 from classes where id = v_class and status = 'active' for share;
  if not found then
    raise exception 'class_archived';
  end if;
  return new;
end;
$$;


--
-- Name: guard_enrollment_student_eligible(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_enrollment_student_eligible() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if not new.active then
    return new;
  end if;
  -- An update that neither activates the row nor moves it enrols no one.
  if tg_op = 'UPDATE' and old.active
     and old.student_id = new.student_id and old.class_id = new.class_id then
    return new;
  end if;

  -- FOR SHARE needs more than SELECT on profiles, which is why this runs as the function owner.
  perform 1 from profiles
   where id = new.student_id and role = 'student' and status <> 'disabled'
   for share;
  if not found then
    raise exception 'student_not_eligible';
  end if;
  return new;
end;
$$;


--
-- Name: guard_profile_privileged_columns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_profile_privileged_columns() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if auth.uid() is null or public.is_active_admin() then
    return new;
  end if;
  if new.role is distinct from old.role
     or new.status is distinct from old.status
     or new.auth_user_id is distinct from old.auth_user_id then
    raise exception 'not allowed to change role, status, or auth_user_id';
  end if;
  return new;
end;
$$;


--
-- Name: increment_resource_download_count(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.increment_resource_download_count(p_resource_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  update resources set download_count = download_count + 1 where id = p_resource_id;
$$;


--
-- Name: institute_month(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.institute_month(p_instant timestamp with time zone) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select to_char(
    p_instant at time zone coalesce(
      (select s.timezone from org_settings s
        where exists (select 1 from pg_timezone_names z where z.name = s.timezone)
        limit 1),
      'Asia/Kolkata'),
    'YYYY-MM');
$$;


--
-- Name: is_active_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_active_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select public.user_is_admin((select id from profiles where auth_user_id = auth.uid()))
$$;


--
-- Name: is_active_sub_admin(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_active_sub_admin() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
