--
-- Name: FUNCTION is_active_sub_admin(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_active_sub_admin() IS 'True when the current caller holds an active global sub_admin persona. Class-scope only - admin-tier powers still gate on is_active_admin().';


--
-- Name: is_app_link(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_app_link(link text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select link is null
      or link = '#'
      or link ~* '^https?://'
      or (link ~ '^/' and link !~ '^//')
$$;


--
-- Name: is_conversation_member(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_conversation_member(p_conversation_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists(
    select 1 from conversation_participants cp
    where cp.conversation_id = p_conversation_id
      and cp.profile_id = current_profile_id()
  )
$$;


--
-- Name: is_enrolled(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_enrolled(p_class_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists(
    select 1
    from enrollments e
    join profiles p on p.id = e.student_id
    join persona_assignments pa
      on pa.profile_id = e.student_id
     and pa.persona_name = 'student'::persona_name
     and pa.scope_type = 'global'::persona_scope_type
     and pa.status = 'active'
    where p.auth_user_id = auth.uid()
      and p.status = 'active'
      and e.class_id = p_class_id
      and e.active
  )
$$;


--
-- Name: is_http_link(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_http_link(link text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public'
    AS $$
  select link is null or link = '#' or link ~* '^https?://'
$$;


--
-- Name: is_self_active(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_self_active(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists(
    select 1 from profiles p
    where p.id = p_id and p.auth_user_id = auth.uid() and p.status = 'active'
  )
$$;


