--

CREATE TABLE public.payslips (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    number text NOT NULL,
    tutor_id uuid,
    tutor_name_snapshot text CONSTRAINT payslips_teacher_name_snapshot_not_null NOT NULL,
    issue_date date DEFAULT CURRENT_DATE NOT NULL,
    currency text NOT NULL,
    note text,
    subtotal numeric(16,3) NOT NULL,
    discount numeric(16,3),
    total numeric(16,3) NOT NULL,
    voided boolean DEFAULT false NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    base_currency text,
    base_total numeric(12,2),
    fx_rate numeric(18,8),
    fx_rate_id uuid,
    billing_period text,
    CONSTRAINT payslips_billing_period_format CHECK (((billing_period IS NULL) OR (billing_period ~ '^\d{4}-(0[1-9]|1[0-2])$'::text)))
);


--
-- Name: COLUMN payslips.billing_period; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.payslips.billing_period IS 'The YYYY-MM this pay slip pays for. Distinct from issue_date. Not unique - see receipts.billing_period.';


--
-- Name: issue_payslip_doc(uuid, text, text, date, text, text, numeric, numeric, numeric, uuid, text, jsonb, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_payslip_doc(p_party_id uuid, p_party_name text, p_class_level text, p_issue_date date, p_currency text, p_note text, p_subtotal numeric, p_discount numeric, p_total numeric, p_created_by uuid, p_prefix text, p_lines jsonb, p_billing_period text DEFAULT NULL::text, p_source_fingerprint text DEFAULT NULL::text, p_source_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.payslips
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_year int;
  v_number text;
  v_counter int;
  v_payslip payslips%rowtype;
begin
  -- p_class_level is accepted but unused: pay slips carry no class snapshot. The parameter
  -- stays so both issue functions keep one shared call shape in the data layer.
  perform assert_issue_allowed('payslip', p_party_id, p_currency, p_total, p_billing_period,
                               p_source_fingerprint, p_source_from, p_source_to);

  v_year := extract(year from p_issue_date);
  v_counter := next_document_number('payslip', v_year);
  v_number := p_prefix || '-' || v_year || '-' || lpad(v_counter::text, 4, '0');

  insert into payslips (
    number, tutor_id, tutor_name_snapshot, issue_date, currency, note,
    subtotal, discount, total, voided, created_by, billing_period
  ) values (
    v_number, p_party_id, p_party_name, p_issue_date, p_currency, p_note,
    p_subtotal, p_discount, p_total, false, p_created_by, p_billing_period
  )
  returning * into v_payslip;

  insert into payslip_lines (payslip_id, label, hours, rate, amount)
  select
    v_payslip.id,
    item->>'label',
    (item->>'hours')::numeric,
    (item->>'rate')::numeric,
    (item->>'amount')::numeric
  from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) item;

  return v_payslip;
end;
$$;


