COMMENT ON COLUMN public.receipts.billing_period IS 'The YYYY-MM this receipt bills for. Distinct from issue_date: a September month is often issued in October. Not unique - one month may legitimately span several documents.';


--
-- Name: issue_receipt_doc(uuid, text, text, date, text, text, numeric, numeric, numeric, uuid, text, jsonb, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.issue_receipt_doc(p_party_id uuid, p_party_name text, p_class_level text, p_issue_date date, p_currency text, p_note text, p_subtotal numeric, p_discount numeric, p_total numeric, p_created_by uuid, p_prefix text, p_lines jsonb, p_billing_period text DEFAULT NULL::text, p_source_fingerprint text DEFAULT NULL::text, p_source_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source_to timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.receipts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_year int;
  v_number text;
  v_counter int;
  v_receipt receipts%rowtype;
begin
  perform assert_issue_allowed('receipt', p_party_id, p_currency, p_total, p_billing_period,
                               p_source_fingerprint, p_source_from, p_source_to);

  v_year := extract(year from p_issue_date);
  v_counter := next_document_number('receipt', v_year);
  v_number := p_prefix || '-' || v_year || '-' || lpad(v_counter::text, 4, '0');

  insert into receipts (
    number, student_id, student_name_snapshot, class_snapshot, issue_date, currency, note,
    subtotal, discount, total, voided, created_by, billing_period
  ) values (
    v_number, p_party_id, p_party_name, p_class_level, p_issue_date, p_currency, p_note,
    p_subtotal, p_discount, p_total, false, p_created_by, p_billing_period
  )
  returning * into v_receipt;

  insert into receipt_lines (receipt_id, subject, hours, rate, amount)
  select
    v_receipt.id,
    item->>'label',
    (item->>'hours')::numeric,
    (item->>'rate')::numeric,
    (item->>'amount')::numeric
  from jsonb_array_elements(coalesce(p_lines, '[]'::jsonb)) item;

  return v_receipt;
end;
$$;


