--
-- Name: make_guardian_primary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.make_guardian_primary(p_student_id uuid, p_guardian_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform pg_advisory_xact_lock(hashtextextended('guardians:' || p_student_id::text, 0));
  perform 1 from guardians where id = p_guardian_id and student_id = p_student_id;
  if not found then
    return false;
  end if;
  -- Two statements, not one: the partial unique index is checked row by row, so clearing the
  -- old primary and setting the new one in a single UPDATE can collide with itself.
  update guardians set is_primary = false
   where student_id = p_student_id and is_primary and id <> p_guardian_id;
  update guardians set is_primary = true where id = p_guardian_id;
  return true;
end;
$$;


--
-- Name: mentors_class(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mentors_class(p_class_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists(
    select 1
    from mentorships m
    join profiles p on p.id = m.mentor_id
    join persona_assignments pa
      on pa.profile_id = m.mentor_id
     and pa.persona_name = 'mentor'::persona_name
     and pa.scope_type = 'student'::persona_scope_type
     and pa.scope_id = m.student_id
     and pa.status = 'active'
    join enrollments e
      on e.student_id = m.student_id
     and e.class_id = p_class_id
     and e.active
    where p.auth_user_id = auth.uid()
      and p.status = 'active'
      and m.active
  )
$$;


--
-- Name: mentors_student(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mentors_student(p_student_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists(
    select 1
    from mentorships m
    join profiles p on p.id = m.mentor_id
    join persona_assignments pa
      on pa.profile_id = m.mentor_id
     and pa.persona_name = 'mentor'::persona_name
     and pa.scope_type = 'student'::persona_scope_type
     and pa.scope_id = m.student_id
     and pa.status = 'active'
    where p.auth_user_id = auth.uid()
      and p.status = 'active'
      and m.student_id = p_student_id
      and m.active
  )
$$;


--
-- Name: next_document_number(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.next_document_number(p_doc_type text, p_year integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare n int;
begin
  insert into document_counters (doc_type, year, last_number)
  values (p_doc_type, p_year, 1)
  on conflict (doc_type, year)
    do update set last_number = document_counters.last_number + 1
  returning last_number into n;
  return n;
end $$;


--
-- Name: messages; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.messages (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    conversation_id uuid NOT NULL,
    sender_id uuid,
    body text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE messages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.messages IS 'Messaging: an immutable message in a conversation. body is plaintext in v1 (server-readable for moderation); structured to allow per-conversation E2EE later without a redesign.';


--
-- Name: post_message(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.post_message(p_conversation_id uuid, p_sender_id uuid, p_body text) RETURNS public.messages
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_message messages%rowtype;
begin
  insert into messages (conversation_id, sender_id, body)
  values (p_conversation_id, p_sender_id, p_body)
  returning * into v_message;

  -- Never move the summary backwards: a send that commits after a later one leaves it alone.
  update conversations
     set last_message_at = v_message.created_at,
         last_message_body = v_message.body,
         last_message_sender_id = v_message.sender_id
   where id = p_conversation_id
     and (last_message_at is null or last_message_at <= v_message.created_at);

  return v_message;
end;
$$;


--
-- Name: rate_limit_hit(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rate_limit_hit(p_key text, p_limit integer, p_window_seconds integer) RETURNS TABLE(allowed boolean, retry_after_seconds integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_now timestamptz := now();
  v_window_started_at timestamptz;
  v_hits integer;
begin
  -- Atomic fixed-window counter: a single upsert both resets an expired window
  -- and increments a live one, so concurrent requests can't race a read/modify.
  insert into public.rate_limit_counters as c (bucket_key, window_started_at, hits)
    values (p_key, v_now, 1)
  on conflict (bucket_key) do update
    set
      window_started_at = case
        when c.window_started_at <= v_now - make_interval(secs => p_window_seconds) then v_now
        else c.window_started_at
      end,
      hits = case
        when c.window_started_at <= v_now - make_interval(secs => p_window_seconds) then 1
        else c.hits + 1
      end
  returning c.window_started_at, c.hits into v_window_started_at, v_hits;

  if v_hits > p_limit then
    return query
      select
        false,
        greatest(
          1,
          ceil(extract(epoch from (v_window_started_at + make_interval(secs => p_window_seconds) - v_now)))
        )::integer;
  else
    return query select true, 0;
  end if;
end;
$$;


--
-- Name: reclassify_submissions_on_due_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reclassify_submissions_on_due_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.due_date is distinct from old.due_date then
    update submissions set
      status = case when submitted_at > new.due_date then 'late' else 'submitted' end
    where assignment_id = new.id
      and status <> (case when submitted_at > new.due_date then 'late' else 'submitted' end);
  end if;
  return new;
end;
$$;


--
-- Name: remove_mentorship(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_mentorship(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_mentor uuid;
  v_student uuid;
begin
  -- Read the pair WITHOUT a row lock, take the pair lock, then write. Locking the row first
  -- would invert assign_mentorship's order (pair lock, then the row) and could deadlock.
  select mentor_id, student_id into v_mentor, v_student from mentorships where id = p_id;
  if not found then
    return false;
  end if;
  perform pg_advisory_xact_lock(hashtextextended('mentorship:' || v_mentor::text || ':' || v_student::text, 0));

  delete from persona_assignments
   where profile_id = v_mentor and persona_name = 'mentor' and scope_type = 'student' and scope_id = v_student;
  update mentorships set active = false where id = p_id;
  return true;
end;
$$;


--
-- Name: submissions; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.submissions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    assignment_id uuid NOT NULL,
    student_id uuid NOT NULL,
    drive_link text,
    file_name text,
    status text NOT NULL,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    score numeric(6,2),
    feedback text,
    graded_at timestamp with time zone,
    graded_by uuid,
    CONSTRAINT submissions_drive_link_scheme CHECK (((drive_link IS NULL) OR (drive_link = '#'::text) OR (drive_link ~* '^https?://'::text))),
    CONSTRAINT submissions_status_check CHECK ((status = ANY (ARRAY['submitted'::text, 'late'::text])))
);


--
-- Name: replace_own_submission(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.replace_own_submission(p_assignment_id uuid, p_drive_link text, p_file_name text DEFAULT NULL::text) RETURNS public.submissions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_assignment assignments%rowtype;
  v_student_id uuid;
  v_current submissions%rowtype;
  v_created submissions%rowtype;
begin
  select *
  into v_assignment
  from assignments
  where id = p_assignment_id and status = 'active';

  if not found then
    raise exception 'assignment_not_found';
  end if;

  -- Hard deadline: once the due instant has passed on an enforce_deadline assignment,
  -- no new/replacement submission is accepted - the rule recordSubmission applies.
  if v_assignment.enforce_deadline and now() > v_assignment.due_date then
    raise exception 'deadline_passed';
  end if;

  select id
  into v_student_id
  from profiles
  where auth_user_id = auth.uid() and status = 'active';

  if v_student_id is null then
    raise exception 'actor_not_active';
  end if;

  if not is_enrolled(v_assignment.class_id) then
    raise exception 'not_enrolled';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(p_assignment_id::text || ':' || v_student_id::text, 0));

  select *
  into v_current
  from submissions
  where assignment_id = p_assignment_id
    and student_id = v_student_id
    and is_active = true
  for update;

  if found and v_current.score is not null then
    raise exception 'submission_already_graded';
  end if;

  update submissions
  set is_active = false
  where assignment_id = p_assignment_id
    and student_id = v_student_id
    and is_active = true;

  insert into submissions (assignment_id, student_id, drive_link, file_name, is_active)
  values (p_assignment_id, v_student_id, p_drive_link, p_file_name, true)
  returning *
  into v_created;

  return v_created;
end;
$$;


--
-- Name: restore_profile_guarded(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_profile_guarded(p_target uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role user_role;
  v_erased timestamptz;
begin
  -- Same key assign_class_tutor and unassign_class_tutor take, so the tutor persona restored
  -- below agrees with the class assignments that exist when this commits.
  perform lock_tutor_persona(p_target);

  select role, erased_at into v_role, v_erased from profiles where id = p_target for update;
  if not found then
    return 'not_found';
  end if;
  -- Erasure is terminal: its sign-in and PII are gone.
  if v_erased is not null then
    return 'erased';
  end if;

  update profiles set status = 'active' where id = p_target;

  -- The persona matching the role (role and persona share their names).
  perform activate_global_persona(p_target, v_role::text::persona_name);
  -- A mentor who also teaches: assignments survive revocation, so their tutor persona returns.
  if exists (select 1 from class_tutors where tutor_id = p_target and active) then
    perform activate_global_persona(p_target, 'tutor');
  end if;
  -- Mentee reach, rebuilt from the surviving mentorship graph.
  insert into persona_assignments (profile_id, persona_name, scope_type, scope_id, status)
  select p_target, 'mentor', 'student', m.student_id, 'active'
    from mentorships m
   where m.mentor_id = p_target and m.active
  on conflict (profile_id, persona_name, scope_id) do update set status = 'active', scope_type = 'student';

  return 'ok';
end;
$$;


--
-- Name: revoke_profile_guarded(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_profile_guarded(p_target uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_role text;
  v_status text;
  v_active_admins int;
begin
  -- Serialize every admin-tier revocation on one constant key, so the last-admin count and
  -- the status flip are a single atomic step across rows.
  perform pg_advisory_xact_lock(hashtextextended('profiles:admin-tier-guard'::text, 0));

  select role, status into v_role, v_status from profiles where id = p_target for update;
  if not found then
    return 'not_found';
  end if;

  if v_role = 'admin' and v_status = 'active' then
    select count(*) into v_active_admins from profiles where role = 'admin' and status = 'active';
    if v_active_admins <= 1 then
      return 'last_admin';
    end if;
  end if;

  update profiles set status = 'disabled' where id = p_target;
  -- Every scope, not just global: a revoked mentor's student-scoped personas are what grant
  -- mentee access. The mentorship and class_tutors rows stay, so restore can rebuild them.
  update persona_assignments set status = 'inactive' where profile_id = p_target;
  return 'ok';
end;
$$;


--
-- Name: rls_disabled_tables(text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rls_disabled_tables(p_tables text[]) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
  select coalesce(array_agg(c.relname order by c.relname), array[]::text[])
  from pg_class c
  join pg_namespace n on n.oid = c.relnamespace
  where n.nspname = 'public'
    and c.relkind = 'r'
    and c.relname = any(p_tables)
    and c.relrowsecurity = false;
$$;


--
-- Name: set_class_subject_when_unset(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_class_subject_when_unset(p_class_id uuid, p_subject_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_current uuid;
  v_labelled integer;
begin
  perform 1 from subjects where id = p_subject_id;
  if not found then
    raise exception 'subject_not_found';
  end if;

  -- The row lock makes "is it still unset?" and the update one step: a second caller waits,
  -- then finds the subject set and is refused.
  select subject_id into v_current from classes where id = p_class_id for update;
  if not found then
    raise exception 'class_not_found';
  end if;
  if v_current is not null then
    raise exception 'subject_already_set';
  end if;

  -- Raises subject_already_taken through trg_student_subject_once.
  update classes set subject_id = p_subject_id where id = p_class_id;

  -- Only sessions that recorded no subject. A class that had none has only ever taught
  -- this one, so this labels history rather than rewriting it.
  update class_sessions set subject_id = p_subject_id
   where class_id = p_class_id and subject_id is null;
  get diagnostics v_labelled = row_count;

  return v_labelled;
end;
$$;


--
-- Name: set_global_capability_override(uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_global_capability_override(p_profile_id uuid, p_capability text, p_effect text, p_reason text, p_actor_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_id uuid;
begin
  if p_effect not in ('allow', 'deny', 'default') then
    raise exception 'invalid_effect';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('capability-override:' || p_profile_id::text || ':' || p_capability, 0));

  -- An override is planted only on an active account: a dormant 'allow' would silently come
  -- back to life on restore. Clearing is always allowed.
  if p_effect <> 'default' then
    perform 1 from profiles where id = p_profile_id and status = 'active' for share;
    if not found then
      raise exception 'target_not_active';
    end if;
  end if;

  delete from capability_overrides
   where profile_id = p_profile_id and capability = p_capability and scope_type = 'global';

  if p_effect = 'default' then
    return null;
  end if;

  insert into capability_overrides (profile_id, capability, effect, scope_type, scope_id, reason, status, created_by)
  values (p_profile_id, p_capability, p_effect, 'global', null, p_reason, 'active', p_actor_id)
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: set_session_subject_from_class(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_session_subject_from_class() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  if new.subject_id is null then
    select c.subject_id into new.subject_id from classes c where c.id = new.class_id;
  end if;
  return new;
end $$;


--
-- Name: set_submission_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_submission_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare due timestamptz;
begin
  new.submitted_at := now();
  select due_date into due from assignments where id = new.assignment_id;
  new.status := case when due is not null and new.submitted_at > due then 'late' else 'submitted' end;
  return new;
end $$;


--
-- Name: set_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: student_takes_subject_elsewhere(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.student_takes_subject_elsewhere(p_student_id uuid, p_subject_id uuid, p_class_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select exists (
    select 1
      from enrollments e
      join classes c on c.id = e.class_id
     where e.student_id = p_student_id
       and e.active
       and e.class_id <> p_class_id
       and c.status <> 'archived'
       and c.subject_id = p_subject_id
  );
$$;


--
-- Name: sum_active_resource_downloads(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sum_active_resource_downloads() RETURNS bigint
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select coalesce(sum(download_count), 0)::bigint
  from resources
  where status = 'active'
$$;


--
-- Name: FUNCTION sum_active_resource_downloads(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.sum_active_resource_downloads() IS 'Total downloads across active documents. Service-role only: it is an academy-wide aggregate for the admin dashboard, not scoped to any caller.';


--
-- Name: teaches_class(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teaches_class(p_class_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists(
    select 1
    from class_tutors ct
    join profiles p on p.id = ct.tutor_id
    join persona_assignments pa
      on pa.profile_id = ct.tutor_id
     and pa.persona_name = 'tutor'::persona_name
     and pa.scope_type = 'global'::persona_scope_type
     and pa.status = 'active'
    where p.auth_user_id = auth.uid()
      and p.status = 'active'
      and ct.class_id = p_class_id
      and ct.active
  )
  or public.mentors_class(p_class_id)
  or public.is_active_sub_admin()
$$;


--
-- Name: teaches_class_write(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.teaches_class_write(p_class_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  select exists(
    select 1
    from class_tutors ct
    join profiles p on p.id = ct.tutor_id
    join persona_assignments pa
      on pa.profile_id = ct.tutor_id
     and pa.persona_name = 'tutor'::persona_name
     and pa.scope_type = 'global'::persona_scope_type
     and pa.status = 'active'
    where p.auth_user_id = auth.uid()
      and p.status = 'active'
      and ct.class_id = p_class_id
      and ct.active
  )
  or public.is_active_sub_admin()
$$;


--
-- Name: unassign_class_tutor(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unassign_class_tutor(p_class_id uuid, p_tutor_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform lock_tutor_persona(p_tutor_id);

  update class_tutors set active = false where class_id = p_class_id and tutor_id = p_tutor_id;
  if not found then
    return false;
  end if;

  -- A dedicated mentor who no longer teaches anything loses the tutor persona teaching gave
  -- them. A tutor keeps theirs: it is their identity, not a grant.
  if exists (select 1 from profiles where id = p_tutor_id and role = 'mentor' and status = 'active')
     and not exists (select 1 from class_tutors where tutor_id = p_tutor_id and active) then
    update persona_assignments set status = 'inactive'
     where profile_id = p_tutor_id and persona_name = 'tutor' and scope_type = 'global';
  end if;
  return true;
end;
$$;


--
-- Name: user_has_persona(uuid, public.persona_name, public.persona_scope_type, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_has_persona(p_user_id uuid, p_persona public.persona_name, p_scope_type public.persona_scope_type DEFAULT 'global'::public.persona_scope_type, p_scope_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return exists (
    select 1
    from persona_assignments pa
    join profiles p on p.id = pa.profile_id and p.status = 'active'
    where pa.profile_id = p_user_id
      and pa.persona_name = p_persona
      and pa.scope_type = p_scope_type
      and (
        (p_scope_type = 'global' and pa.scope_id is null) or
        (p_scope_type != 'global' and pa.scope_id = p_scope_id)
      )
      and pa.status = 'active'
  );
end;
$$;


--
-- Name: user_is_admin(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_is_admin(p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return user_has_persona(p_user_id, 'admin'::persona_name);
end;
$$;


--
-- Name: user_is_mentor_for_student(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.user_is_mentor_for_student(p_user_id uuid, p_student_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  return user_has_persona(
    p_user_id,
    'mentor'::persona_name,
    'student'::persona_scope_type,
    p_student_id
  );
end;
$$;


