-- Name: class_sessions class_sessions_delete; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY class_sessions_delete ON public.class_sessions FOR DELETE USING (public.is_active_admin());


--
-- Name: class_sessions class_sessions_insert; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY class_sessions_insert ON public.class_sessions FOR INSERT WITH CHECK ((public.is_active_admin() OR public.teaches_class(class_id)));


--
-- Name: class_sessions class_sessions_read; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY class_sessions_read ON public.class_sessions FOR SELECT USING ((public.is_active_admin() OR public.teaches_class(class_id) OR (EXISTS ( SELECT 1
   FROM (public.attendance a
     JOIN public.profiles p ON ((p.id = a.student_id)))
  WHERE ((a.session_id = class_sessions.id) AND (p.auth_user_id = auth.uid()) AND (p.status = 'active'::public.user_status))))));


--
-- Name: POLICY class_sessions_read ON class_sessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON POLICY class_sessions_read ON public.class_sessions IS 'Admins and the class''s teaching staff read every session; a student reads only the sessions they were MARKED for (attendance.session_id), not every session on a date they attended something.';


--
-- Name: class_sessions class_sessions_student_feedback_update; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY class_sessions_student_feedback_update ON public.class_sessions FOR UPDATE TO authenticated USING ((public.is_enrolled(class_id) AND (EXISTS ( SELECT 1
   FROM public.attendance a
  WHERE ((a.session_id = class_sessions.id) AND (a.student_id = public.current_profile_id())))))) WITH CHECK ((public.is_enrolled(class_id) AND (EXISTS ( SELECT 1
   FROM public.attendance a
  WHERE ((a.session_id = class_sessions.id) AND (a.student_id = public.current_profile_id()))))));


--
-- Name: POLICY class_sessions_student_feedback_update ON class_sessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON POLICY class_sessions_student_feedback_update ON public.class_sessions IS 'A student may write feedback only on a session they were marked for. Column access is separately restricted to student_feedback (0068), so this cannot touch a summary or a staff note.';


