--
-- Table privilege epilogue (R-01)
-- ============================================================================
-- The migration chain REVOKEs Supabase's table-wide default grants, then GRANTs back the
-- specific columns each role may touch. A schema-only dump keeps the column GRANTs but
-- drops the table-wide REVOKEs, so re-apply them HERE, BEFORE the ACL section, because:
--   1. ORDER - a table-level REVOKE cascades to that table's COLUMN privileges, so a
--      REVOKE after the column GRANTs wipes them (withdraw / self-service / session read
--      break). Revoking first, then letting the ACL GRANTs below re-establish the
--      columns, mirrors the chain (revoke in 0033, grant in 0064/0065).
--   2. QUALIFICATION - pg_dump empties search_path, so an unqualified name errors and
--      silently does nothing. Every name here is public.<table>.
-- ============================================================================
REVOKE INSERT, UPDATE ON TABLE public.submissions FROM authenticated;
REVOKE SELECT ON TABLE public.class_sessions FROM authenticated;
REVOKE INSERT, UPDATE, DELETE ON TABLE public.class_sessions FROM anon, authenticated;
REVOKE INSERT, UPDATE, DELETE ON TABLE public.attendance FROM anon, authenticated;
REVOKE UPDATE ON TABLE public.notifications FROM anon, authenticated;
REVOKE UPDATE ON TABLE public.profiles FROM authenticated;
REVOKE ALL ON TABLE public.reminders FROM authenticated;
REVOKE ALL ON TABLE public.billing_rates FROM anon, authenticated;
--
-- Name: FUNCTION activate_attachment(p_id uuid, p_drive_file_id text, p_drive_folder_id text, p_max_active integer); Type: ACL; Schema: public; Owner: -
--

REVOKE ALL ON FUNCTION public.activate_attachment(p_id uuid, p_drive_file_id text, p_drive_folder_id text, p_max_active integer) FROM PUBLIC;
GRANT ALL ON FUNCTION public.activate_attachment(p_id uuid, p_drive_file_id text, p_drive_folder_id text, p_max_active integer) TO service_role;


--
-- Name: FUNCTION activate_global_persona(p_profile_id uuid, p_persona public.persona_name); Type: ACL; Schema: public; Owner: -
--

REVOKE ALL ON FUNCTION public.activate_global_persona(p_profile_id uuid, p_persona public.persona_name) FROM PUBLIC;


--
-- Name: FUNCTION add_guardian(p_student_id uuid, p_name text, p_phone text, p_email text, p_relationship text, p_is_primary boolean); Type: ACL; Schema: public; Owner: -
--

REVOKE ALL ON FUNCTION public.add_guardian(p_student_id uuid, p_name text, p_phone text, p_email text, p_relationship text, p_is_primary boolean) FROM PUBLIC;
GRANT ALL ON FUNCTION public.add_guardian(p_student_id uuid, p_name text, p_phone text, p_email text, p_relationship text, p_is_primary boolean) TO service_role;


